const workPlanUpsert = `-- name: WorkPlanUpsert :one
INSERT INTO work_plan (id, project_id, scope_kind, scope_id, version, title, goal, strategy, payload)
VALUES ($1, $2, $3, $4, 1, $5, $6, $7, $8)
ON CONFLICT (scope_kind, scope_id) DO UPDATE SET
 title = excluded.title,
 goal = excluded.goal,
 strategy = excluded.strategy,
 payload = excluded.payload,
 version = work_plan.version + 1,
 updated_at = now()
WHERE work_plan.project_id = excluded.project_id
  AND work_plan.tombstoned_at IS NULL
RETURNING id, project_id, scope_kind, scope_id, version, title, goal, strategy, payload, created_at, updated_at, tombstoned_at
`

type WorkPlanUpsertParams struct {
	ID        string
	ProjectID string
	ScopeKind string
	ScopeID   string
	Title     string
	Goal      string
	Strategy  string
	Payload   []byte
}

func (q *Queries) WorkPlanUpsert(ctx context.Context, arg WorkPlanUpsertParams) (WorkPlan, error) {
	row := q.db.QueryRow(ctx, workPlanUpsert,
		arg.ID,
		arg.ProjectID,
		arg.ScopeKind,
		arg.ScopeID,
		arg.Title,
		arg.Goal,
		arg.Strategy,
		arg.Payload,
	)
	var i WorkPlan
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.ScopeKind,
		&i.ScopeID,
		&i.Version,
		&i.Title,
		&i.Goal,
		&i.Strategy,
		&i.Payload,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.TombstonedAt,
	)
	return i, err
}
